$w = ( isset($p['weight_kg']) && $p['weight_kg']!=='' && $p['weight_kg']!==null ) ? (float)$p['weight_kg'] : null;
if ( $pet_id<=0 || $w===null || $w<=0 || $w>200 ) return new WP_REST_Response(array('ok'=>false,'error'=>'bad_input'),400);
global $wpdb; $pf=$wpdb->prefix;
$own = (int)$wpdb->get_var($wpdb->prepare("SELECT user_id FROM {$pf}ps_pets WHERE id=%d AND deleted_at IS NULL",$pet_id));
if ( $own !== (int)get_current_user_id() ) return new WP_REST_Response(array('ok'=>false,'error'=>'forbidden'),403);
// S348: weight_updated_at = KADA SVORIS PASIKEITE (ta pati semantika kaip
// class-pet-profile S345). Skaitinis palyginimas — DB laiko "12.50".
// gmdate, ne current_time: kanoninis kelias raso UTC; du laikrodziai
// viename stulpelyje dave 3 val. suoli (V6 radinys).
$dab = $wpdb->get_var($wpdb->prepare("SELECT current_weight_kg FROM {$pf}ps_pets WHERE id=%d",$pet_id));
$upd = array('current_weight_kg'=>$w,'updated_at'=>gmdate('Y-m-d H:i:s'));
if ( $dab === null || abs((float)$dab - $w) > 0.001 ) { $upd['weight_updated_at'] = gmdate('Y-m-d H:i:s'); }
$wpdb->update($pf.'ps_pets', $upd, array('id'=>$pet_id));
return new WP_REST_Response(array('ok'=>true,'weight_kg'=>$w),200);
},
));
